/**
 * W1.4 — phone sign-up / sign-in through the real local auth server and the `send-sms` hook.
 *
 * Codes are generated by the auth server and verified by it. The hook's local "sink" provider
 * posts each SMS to a tiny HTTP server started here (the SMS equivalent of the local mail
 * catcher), so these tests read the real code; nothing is simulated or bypassed.
 * Needs: `supabase start` (hook configured in config.toml) and
 * `supabase functions serve --env-file supabase/functions/.env.test`.
 */
import { createHmac, randomInt } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { createServer, type Server } from 'node:http';
import { join } from 'node:path';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { SUPABASE_ANON_KEY, SUPABASE_URL } from './env';
import { adminClient, anonClient, createUser, expectPermissionDenied, psql, rpc, trackUser, waitFor } from './helpers';

const ENV_TEST = readFileSync(join(__dirname, '../../../supabase/functions/.env.test'), 'utf8');
const envValue = (key: string) => ENV_TEST.match(new RegExp(`^${key}=(.+)$`, 'm'))?.[1]?.trim() ?? '';
const HOOK_SECRET = envValue('SEND_SMS_HOOK_SECRET');
const LOG_KEY = envValue('SMS_LOG_KEY');

interface Sms {
  to: string;
  text: string;
  hook_id: string;
}
const inbox: Sms[] = [];
let sink: Server;

/** A fresh number in a Senegalese mobile range (+221 77/76/70/75/78 …). */
function senegalNumber(prefix = '77'): string {
  return `+221${prefix}${String(randomInt(0, 10_000_000)).padStart(7, '0')}`;
}

async function codeFor(phone: string, after = 0): Promise<string> {
  const sms = await waitFor(async () => inbox.slice(after).reverse().find((m) => m.to === phone) ?? null, 10_000);
  const code = sms.text.match(/(\d{6})/)?.[1];
  if (!code) throw new Error(`no code in « ${sms.text} »`);
  return code;
}

async function authPost(path: string, body: unknown, bearer?: string, method = 'POST') {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/${path}`, {
    method,
    headers: { apikey: SUPABASE_ANON_KEY, 'Content-Type': 'application/json', ...(bearer ? { Authorization: `Bearer ${bearer}` } : {}) },
    body: JSON.stringify(body),
  });
  return { status: res.status, body: (await res.json().catch(() => ({}))) as Record<string, any> };
}

function phoneKey(phone: string): string {
  return createHmac('sha256', LOG_KEY).update(`phone:${phone.replace(/\D/g, '')}`).digest('hex');
}

function setFlag(enabled: boolean) {
  psql(`update public.feature_flags set enabled = ${enabled} where key = 'phone_auth'`);
}

async function signHook(body: string, id: string, ts = Math.floor(Date.now() / 1000)) {
  const key = Buffer.from(HOOK_SECRET.replace(/^v1,whsec_/, ''), 'base64');
  const sig = createHmac('sha256', key).update(`${id}.${ts}.${body}`).digest('base64');
  return { 'webhook-id': id, 'webhook-timestamp': String(ts), 'webhook-signature': `v1,${sig}`, 'Content-Type': 'application/json' };
}

/** Phone sign-up through the auth API exactly as the app does it. Returns the session. */
async function phoneSignUp(phone: string, displayName = 'Awa Test') {
  const before = inbox.length;
  const otp = await authPost('otp', { phone, create_user: true, data: { display_name: displayName } });
  expect(otp.status, JSON.stringify(otp.body)).toBe(200);
  const code = await codeFor(phone, before);
  const verified = await authPost('verify', { type: 'sms', phone, token: code });
  expect(verified.status, JSON.stringify(verified.body)).toBe(200);
  trackUser(verified.body.user.id);
  return verified.body as { access_token: string; user: { id: string; email: string; phone: string; phone_confirmed_at: string | null } };
}

beforeAll(async () => {
  expect(HOOK_SECRET, 'SEND_SMS_HOOK_SECRET in .env.test').toMatch(/^v1,whsec_/);
  sink = createServer((req, res) => {
    let raw = '';
    req.on('data', (c) => (raw += c));
    req.on('end', () => {
      try {
        inbox.push(JSON.parse(raw) as Sms);
      } catch {
        /* ignore */
      }
      res.writeHead(200, { 'Content-Type': 'application/json' }).end('{}');
    });
  });
  await new Promise<void>((resolve) => sink.listen(54399, '0.0.0.0', resolve));
  setFlag(true);
  // Every local request reaches the auth server from the same Docker gateway address: lift
  // the per-IP cap for this file (the IP test below sets it explicitly).
  psql(`update private.sms_settings set per_ip_hour = 1000 where id`);
});

afterAll(async () => {
  setFlag(false);
  psql(`update private.sms_settings set daily_budget = 300, per_ip_hour = 10 where id`); // migration defaults
  await new Promise<void>((resolve) => sink.close(() => resolve()));
});

describe('phone sign-up and sign-in (+221)', () => {
  it('signs up with a real code: phone-only account, profile created, no e-mail, code single-use', async () => {
    const phone = senegalNumber();
    const before = inbox.length;
    const session = await phoneSignUp(phone, 'Awa Téléphone');
    expect(session.user.email ?? '').toBe('');
    expect(session.user.phone).toBe(phone.slice(1));
    expect(session.user.phone_confirmed_at).not.toBeNull();

    const sms = inbox.slice(before).find((m) => m.to === phone)!;
    expect(sms.text).toMatch(/^Jëfëli : votre code est \d{6}\. Ne le partagez avec personne\.$/);
    expect(sms.text.length).toBeLessThanOrEqual(70); // one SMS segment

    const profile = (await adminClient.from('profiles').select('display_name, handle').eq('id', session.user.id).single()).data!;
    expect(profile.display_name).toBe('Awa Téléphone');
    expect(profile.handle).toMatch(/^membre/); // neutral: never derived from the number
    const settings = await adminClient.from('account_settings').select('user_id').eq('user_id', session.user.id);
    expect(settings.data).toHaveLength(1);

    const code = sms.text.match(/(\d{6})/)![1];
    const replay = await authPost('verify', { type: 'sms', phone, token: code });
    expect(replay.status).toBe(403);
    expect(replay.body.error_code).toBe('otp_expired');
  });

  it('signs in again with a new code; a wrong code is refused', async () => {
    const phone = senegalNumber('76');
    const first = await phoneSignUp(phone);
    // Supabase enforces 60 s between two codes to the same number.
    const tooSoon = await authPost('otp', { phone, create_user: false });
    expect(tooSoon.status).toBe(429);
    expect(tooSoon.body.error_code).toBe('over_sms_send_rate_limit');

    psql(`update auth.users set confirmation_sent_at = now() - interval '2 minutes', recovery_sent_at = now() - interval '2 minutes' where id = '${first.user.id}'`);
    const before = inbox.length;
    const otp = await authPost('otp', { phone, create_user: false });
    expect(otp.status, JSON.stringify(otp.body)).toBe(200);
    const code = await codeFor(phone, before);

    const wrong = await authPost('verify', { type: 'sms', phone, token: code === '000000' ? '111111' : '000000' });
    expect(wrong.status).toBe(403);
    const ok = await authPost('verify', { type: 'sms', phone, token: code });
    expect(ok.status).toBe(200);
    expect(ok.body.user.id).toBe(first.user.id);
  });

  it('does not create an account from the sign-in screen for an unknown number', async () => {
    const phone = senegalNumber();
    const res = await authPost('otp', { phone, create_user: false });
    expect(res.status).toBe(422);
    expect(res.body.error_code).toBe('otp_disabled');
    expect(inbox.some((m) => m.to === phone)).toBe(false);
  });

  it('an expired code is refused', async () => {
    const phone = senegalNumber('70');
    const before = inbox.length;
    expect((await authPost('otp', { phone, create_user: true })).status).toBe(200);
    const code = await codeFor(phone, before);
    const id = psql(`select id from auth.users where phone = '${phone.slice(1)}'`);
    trackUser(id);
    psql(`update auth.users set confirmation_sent_at = now() - interval '2 days' where id = '${id}'`);
    const res = await authPost('verify', { type: 'sms', phone, token: code });
    expect(res.status).toBe(403);
    expect(res.body.error_code).toBe('otp_expired');
  });
});

describe('send-sms hook guard (server side)', () => {
  it('refuses numbers outside the allowed Senegal mobile ranges, before any SMS and any account', async () => {
    for (const phone of ['+221710000001', '+33612345678', '+2203012345']) {
      const res = await authPost('otp', { phone, create_user: true });
      expect(res.status, phone).toBe(400);
      expect(res.body.msg).toBe('sms_destination_not_allowed');
      expect(inbox.some((m) => m.to === phone)).toBe(false);
      expect(psql(`select count(*) from auth.users where phone = '${phone.slice(1)}'`)).toBe('0');
    }
  });

  it('the phone_auth switch stops sending on the server too', async () => {
    setFlag(false);
    try {
      const phone = senegalNumber();
      const res = await authPost('otp', { phone, create_user: true });
      expect(res.status).toBe(403);
      expect(res.body.msg).toBe('sms_disabled');
      expect(inbox.some((m) => m.to === phone)).toBe(false);
    } finally {
      setFlag(true);
    }
  });

  it('caps codes per number per hour', async () => {
    const phone = senegalNumber();
    const key = phoneKey(phone);
    psql(`insert into private.sms_events (phone_key, phone_prefix, outcome, provider) select '${key}', '22177', 'sent', 'sink' from generate_series(1, 3)`);
    const res = await authPost('otp', { phone, create_user: true });
    expect(res.status).toBe(429);
    expect(res.body.msg).toBe('sms_limit_number');
    expect(inbox.some((m) => m.to === phone)).toBe(false);
    expect(psql(`select reason from private.sms_events where phone_key = '${key}' and outcome = 'blocked'`)).toBe('number_hour');
  });

  it('caps the whole project per day (budget)', async () => {
    psql(`update private.sms_settings set daily_budget = 0 where id`);
    try {
      const res = await authPost('otp', { phone: senegalNumber(), create_user: true });
      expect(res.status).toBe(429);
      expect(res.body.msg).toBe('sms_daily_budget');
    } finally {
      psql(`update private.sms_settings set daily_budget = 300 where id`);
    }
  });

  it('caps codes per IP address', async () => {
    // Earlier tests in this file sent from the same local address: start from a clean hour.
    psql(`delete from private.sms_events where created_at > now() - interval '1 hour'`);
    psql(`update private.sms_settings set per_ip_hour = 1 where id`);
    try {
      const first = senegalNumber();
      const firstRes = await authPost('otp', { phone: first, create_user: true });
      expect(firstRes.status, JSON.stringify(firstRes.body)).toBe(200);
      trackUser(psql(`select id from auth.users where phone = '${first.slice(1)}'`));
      const second = await authPost('otp', { phone: senegalNumber(), create_user: true });
      expect(second.status).toBe(429);
      expect(second.body.msg).toBe('sms_limit_ip');
    } finally {
      psql(`update private.sms_settings set per_ip_hour = 1000 where id`);
    }
  });

  it('rejects unsigned, forged and stale hook calls; a retried call never sends twice', async () => {
    const url = `${SUPABASE_URL}/functions/v1/send-sms`;
    const phone = senegalNumber();
    const body = JSON.stringify({ metadata: { ip_address: '10.9.9.9' }, user: { phone: phone.slice(1) }, sms: { otp: '424242', phone: phone.slice(1) } });

    expect((await fetch(url, { method: 'POST', body })).status).toBe(401);
    const forged = await signHook(body, 'forged-1');
    forged['webhook-signature'] = 'v1,AAAA' + forged['webhook-signature'].slice(7);
    expect((await fetch(url, { method: 'POST', headers: forged, body })).status).toBe(401);
    expect((await fetch(url, { method: 'POST', headers: await signHook(body, 'stale-1', Math.floor(Date.now() / 1000) - 3600), body })).status).toBe(401);

    const id = `retry-${Date.now()}`;
    const headers = await signHook(body, id);
    expect((await fetch(url, { method: 'POST', headers, body })).status).toBe(200);
    expect((await fetch(url, { method: 'POST', headers, body })).status).toBe(200);
    await waitFor(async () => inbox.some((m) => m.hook_id === id));
    expect(inbox.filter((m) => m.hook_id === id)).toHaveLength(1);
    expect(psql(`select outcome || ':' || provider from private.sms_events where hook_id = '${id}'`)).toBe('sent:sink');
    psql(`delete from private.sms_events where hook_id = '${id}'`);
  });

  it('stores no code and no full number in the usage log', async () => {
    const phone = senegalNumber();
    await phoneSignUp(phone);
    const digits = phone.slice(1);
    const rows = psql(`select row_to_json(e)::text from private.sms_events e where phone_key = '${phoneKey(phone)}'`);
    expect(rows).not.toBe('');
    expect(rows).not.toContain(digits);
    expect(rows).not.toMatch(/"reason":"\d{6}"/);
    expect(rows).toContain('"phone_prefix":"22177"');
  });
});

describe('adding a verified phone to an existing e-mail account', () => {
  it('attaches the number to the same account: no second profile, boutique or listings', async () => {
    const member = await createUser('mail', { onboarded: true });
    const phone = senegalNumber('78');
    const before = inbox.length;
    const change = await authPost('user', { phone }, member.accessToken, 'PUT');
    expect(change.status, JSON.stringify(change.body)).toBe(200);
    const code = await codeFor(phone, before);
    const verified = await authPost('verify', { type: 'phone_change', phone, token: code }, member.accessToken);
    expect(verified.status, JSON.stringify(verified.body)).toBe(200);
    expect(verified.body.user.id).toBe(member.id);
    expect(verified.body.user.email).toBe(member.email);
    expect(verified.body.user.phone).toBe(phone.slice(1));
    expect(psql(`select count(*) from auth.users where phone = '${phone.slice(1)}'`)).toBe('1');
    expect(psql(`select count(*) from public.profiles where id = '${member.id}'`)).toBe('1');

    // The member can now sign in with the number and lands on the same account.
    psql(`update auth.users set phone_change_sent_at = now() - interval '2 minutes', confirmation_sent_at = now() - interval '2 minutes', recovery_sent_at = now() - interval '2 minutes' where id = '${member.id}'`);
    const again = inbox.length;
    expect((await authPost('otp', { phone, create_user: false })).status).toBe(200);
    const login = await authPost('verify', { type: 'sms', phone, token: await codeFor(phone, again) });
    expect(login.status).toBe(200);
    expect(login.body.user.id).toBe(member.id);
  });

  it('refuses a number that already belongs to another account (no merge, no duplicate)', async () => {
    const phone = senegalNumber();
    await phoneSignUp(phone);
    const member = await createUser('mail2');
    const res = await authPost('user', { phone }, member.accessToken, 'PUT');
    expect(res.status).toBe(422);
    expect(res.body.error_code).toBe('phone_exists');
    expect(psql(`select coalesce(phone, '') from auth.users where id = '${member.id}'`)).toBe('');
  });
});

describe('phone-only accounts: export, deletion, privacy', () => {
  it('exports the phone number and deletes cleanly, forgetting the usage-log link', async () => {
    const phone = senegalNumber();
    const session = await phoneSignUp(phone);
    const exported = await fetch(`${SUPABASE_URL}/rest/v1/rpc/export_my_data`, {
      method: 'POST',
      headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${session.access_token}`, 'Content-Type': 'application/json' },
      body: '{}',
    });
    expect(exported.status).toBe(200);
    const data = (await exported.json()) as { account: { phone: string; email: string | null } };
    expect(data.account.phone).toBe(phone.slice(1));

    expect(psql(`select count(*) from private.sms_events where user_id = '${session.user.id}'`)).not.toBe('0');
    const del = await fetch(`${SUPABASE_URL}/functions/v1/delete-account`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${session.access_token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ confirm: true }),
    });
    expect(del.status).toBe(200);
    expect(psql(`select count(*) from auth.users where id = '${session.user.id}'`)).toBe('0');
    expect(psql(`select count(*) from private.sms_events where user_id = '${session.user.id}'`)).toBe('0');
  });

  it('members cannot call the hook functions or read the log; usage stats are admin-only', async () => {
    const member = await createUser('member');
    const anon = anonClient();
    for (const client of [anon, member.client]) {
      expectPermissionDenied(await client.rpc('sms_hook_begin', { p_hook_id: 'x', p_phone_key: 'a'.repeat(64), p_phone_prefix: '22177' }));
      expectPermissionDenied(await client.rpc('sms_hook_finish', { p_event_id: 1, p_outcome: 'sent', p_provider: 'sink' }));
    }
    const denied = await member.client.rpc('admin_sms_usage', { p_days: 7 });
    expect(denied.error?.message).toBe('not_allowed');
    expectPermissionDenied(await anon.rpc('admin_sms_usage', { p_days: 7 }));

    const adminUser = await createUser('admin', { staffRole: 'admin' });
    const usage = await rpc<{ day: string; sent: number; blocked: number; est_cost_xof: number }[]>(adminUser.client, 'admin_sms_usage', { p_days: 7 });
    expect(usage.length).toBeGreaterThan(0);
    expect(Number(usage[0]!.sent)).toBeGreaterThan(0);
  });
});
